// FRIS visualisation engine — dependency-free SVG. Interactive force-directed
// network graph, Sankey flows, bar/donut/factor charts and a schematic
// jurisdiction map. Resolution-independent via a fixed viewBox.
import { el, icon } from './core.js';

const SVGNS = 'http://www.w3.org/2000/svg';
function S(tag, attrs = {}, ...kids) {
  const e = document.createElementNS(SVGNS, tag);
  for (const [k, v] of Object.entries(attrs)) { if (v == null) continue; if (k.startsWith('on') && typeof v === 'function') e.addEventListener(k.slice(2).toLowerCase(), v); else e.setAttribute(k, v); }
  for (const kid of kids.flat()) if (kid != null) e.append(kid);
  return e;
}

/* ---------- Sankey ---------- */
export function sankey(container, opts = {}) {
  const links = (opts.links || []).map((l) => ({ ...l, v: Number(l.valueMinor != null ? l.valueMinor : l.value) }));
  const H = opts.height || 340, W = 960, PAD = 8;
  const names = [...new Set(links.flatMap((l) => [l.from, l.to]))];
  // column assignment by longest path from sources
  const col = new Map(names.map((n) => [n, 0]));
  for (let i = 0; i < names.length; i++) for (const l of links) col.set(l.to, Math.max(col.get(l.to), col.get(l.from) + 1));
  const maxCol = Math.max(0, ...[...col.values()]);
  const byCol = {};
  for (const n of names) (byCol[col.get(n)] ||= []).push(n);
  const inflow = new Map(), outflow = new Map();
  for (const l of links) { outflow.set(l.from, (outflow.get(l.from) || 0) + l.v); inflow.set(l.to, (inflow.get(l.to) || 0) + l.v); }
  const val = (n) => Math.max(inflow.get(n) || 0, outflow.get(n) || 0) || 1;
  const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, height: H });
  const colW = W / (maxCol + 1);
  const pos = new Map();
  for (let c = 0; c <= maxCol; c++) {
    const col_ = byCol[c] || [];
    const total = col_.reduce((a, n) => a + val(n), 0) || 1;
    let y = PAD;
    const avail = H - PAD * 2 - (col_.length - 1) * 10;
    for (const n of col_) { const h = Math.max(6, (val(n) / total) * avail); pos.set(n, { x: c * colW + colW * 0.2, y, w: colW * 0.16, h }); y += h + 10; }
  }
  // links
  const cursor = new Map();
  for (const l of links.sort((a, b) => col.get(a.from) - col.get(b.from))) {
    const s = pos.get(l.from), t = pos.get(l.to); if (!s || !t) continue;
    const sTot = outflow.get(l.from) || 1, tTot = inflow.get(l.to) || 1;
    const sh = (l.v / sTot) * s.h, th = (l.v / tTot) * t.h;
    const sy = (cursor.get('o' + l.from) || s.y) , ty = (cursor.get('i' + l.to) || t.y);
    cursor.set('o' + l.from, sy + sh); cursor.set('i' + l.to, ty + th);
    const x1 = s.x + s.w, x2 = t.x, mx = (x1 + x2) / 2;
    const path = S('path', { d: `M${x1},${sy + sh / 2} C${mx},${sy + sh / 2} ${mx},${ty + th / 2} ${x2},${ty + th / 2}`, stroke: linkColor(l.to), 'stroke-width': Math.max(1.5, Math.min(sh, th)), fill: 'none', opacity: 0.32 });
    const title = S('title', {}, `${l.from} → ${l.to}: ${l.value}`);
    path.append(title);
    path.addEventListener('mouseenter', () => path.setAttribute('opacity', 0.6));
    path.addEventListener('mouseleave', () => path.setAttribute('opacity', 0.32));
    svg.append(path);
  }
  for (const [n, p] of pos) {
    svg.append(S('rect', { x: p.x, y: p.y, width: p.w, height: p.h, rx: 2, fill: linkColor(n) }));
    const right = col.get(n) < maxCol / 2;
    svg.append(S('text', { x: right ? p.x + p.w + 5 : p.x - 5, y: p.y + p.h / 2 + 3, 'text-anchor': right ? 'start' : 'end', fill: '#aab6c8', 'font-size': 10 }, n));
  }
  container.classList.add('viz'); container.replaceChildren(svg);
  function linkColor(name) { const n = name.toLowerCase(); if (n.includes('loss') || n.includes('cost') || n.includes('enforcement')) return '#f0616d'; if (n.includes('secured')) return '#37c2b4'; if (n.includes('preferential')) return '#4d8df0'; if (n.includes('unsecured')) return '#e5a53b'; if (n.includes('residual') || n.includes('shareholder')) return '#a97bf0'; if (n.includes('clawback')) return '#46b877'; return '#8aa0bd'; }
}

/* ---------- Charts ---------- */
export function barChart(container, data, opts = {}) {
  const H = opts.height || 200, W = 480, PAD = 26;
  const max = Math.max(1, ...data.map((d) => d.value));
  const bw = (W - PAD) / data.length;
  const svg = S('svg', { viewBox: `0 0 ${W} ${H}`, height: H });
  data.forEach((d, i) => {
    const h = (d.value / max) * (H - 40);
    const x = PAD + i * bw + bw * 0.12, y = H - 22 - h;
    svg.append(S('rect', { x, y, width: bw * 0.76, height: h, rx: 3, fill: d.color || '#4d8df0' }));
    svg.append(S('text', { x: x + bw * 0.38, y: y - 4, 'text-anchor': 'middle', fill: '#aab6c8', 'font-size': 10 }, d.value));
    svg.append(S('text', { x: x + bw * 0.38, y: H - 7, 'text-anchor': 'middle', fill: '#7d8aa0', 'font-size': 9 }, String(d.label).slice(0, 10)));
  });
  container.replaceChildren(svg);
}
export function donut(container, segments, opts = {}) {
  const total = segments.reduce((a, s) => a + s.value, 0) || 1;
  const R = 60, r = 38, C = 80, H = 160;
  const svg = S('svg', { viewBox: `0 0 ${H} ${H}`, height: opts.height || 160 });
  let a0 = -Math.PI / 2;
  for (const s of segments) { const a1 = a0 + (s.value / total) * Math.PI * 2; const large = a1 - a0 > Math.PI ? 1 : 0; const x0 = C + Math.cos(a0) * R, y0 = C + Math.sin(a0) * R, x1 = C + Math.cos(a1) * R, y1 = C + Math.sin(a1) * R; const xi0 = C + Math.cos(a1) * r, yi0 = C + Math.sin(a1) * r, xi1 = C + Math.cos(a0) * r, yi1 = C + Math.sin(a0) * r; svg.append(S('path', { d: `M${x0},${y0} A${R},${R} 0 ${large} 1 ${x1},${y1} L${xi0},${yi0} A${r},${r} 0 ${large} 0 ${xi1},${yi1} Z`, fill: s.color || '#4d8df0' })); a0 = a1; }
  svg.append(S('text', { x: C, y: C - 2, 'text-anchor': 'middle', fill: '#e7edf5', 'font-size': 20, 'font-weight': 700 }, String(total)));
  svg.append(S('text', { x: C, y: C + 14, 'text-anchor': 'middle', fill: '#7d8aa0', 'font-size': 9 }, opts.label || ''));
  container.replaceChildren(svg);
}

/* ---------- Jurisdiction map (zoomable cartographic world) ----------
 * Framework-free, offline, deterministic. Equirectangular projection
 * (lon -180..180 -> x, lat 90..-90 -> y). Land is drawn from the compact,
 * simplified continent outlines below (static [lon,lat] rings - recognizable
 * coastlines at low resolution, no network/tiles). Markers are legal
 * jurisdictions plotted at their real lat/lon: colour encodes secrecy/risk,
 * radius encodes entity count, offshore centres get a badge ring. Markers
 * hold a constant screen size under zoom. A detail panel, legend and ranked
 * summary make it operationally useful.
 */
/* ---------- Accurate world coastlines (Feature 3) ----------
 * Natural-Earth-derived country coastlines (johan/world.geo.json, WGS84), fetched at
 * BUILD time and simplified with Douglas-Peucker (epsilon 0.5°) into a compact static
 * equirectangular [lon,lat] polygon set — no runtime network. ~200 rings / ~2.8k points
 * covering every continent and the major islands (British Isles, Ireland, Cyprus, Sicily,
 * Crete, Cuba, Japan, Indonesia, Madagascar, New Zealand…). Micro-island financial
 * centres below that resolution (Cayman, BVI, Jersey, Guernsey, Malta, Singapore) are
 * added as tiny islets in ISLAND_DOTS so their markers read as land, not open ocean.
 * The jurisdiction points + cross-border pathways still come from the live API.
 */
const ISLAND_DOTS = [
  { lon: -81.25, lat: 19.31, r: 0.9 },  // Cayman Islands
  { lon: -64.64, lat: 18.42, r: 0.7 },  // British Virgin Islands
  { lon: -2.13, lat: 49.21, r: 0.5 },   // Jersey
  { lon: -2.59, lat: 49.47, r: 0.45 },  // Guernsey
  { lon: 14.51, lat: 35.90, r: 0.5 },   // Malta
  { lon: 103.82, lat: 1.35, r: 0.7 },   // Singapore
];
